import{c as l,Q as a,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const e="/assets/SIMD%E4%B8%8ESIMT%E6%B7%B7%E5%90%88%E7%BC%96%E7%A8%8B%E7%A1%AC%E4%BB%B6%E6%9E%B6%E6%9E%84%E5%9B%BE.ChbZTCbI.png",o="/assets/SIMD%E4%B8%8ESIMT%E6%B7%B7%E5%90%88%E7%BC%96%E7%A8%8B%E5%86%85%E5%AD%98%E6%A8%A1%E5%9E%8B%E7%A4%BA%E6%84%8F%E5%9B%BE.B-ZUuXYU.png",p="/assets/UB%E5%86%85%E5%AD%98%E5%88%86%E9%85%8D%E5%9B%BE.CuwfZLGA.png",i="/assets/%E5%87%BD%E6%95%B0%E8%B0%83%E7%94%A8%E5%85%B3%E7%B3%BB%E5%9B%BE.DaeGdKZi.png",I=JSON.parse('{"title":"SIMD与SIMT混合编程","description":"","frontmatter":{},"headers":[{"level":1,"title":"SIMD与SIMT混合编程","slug":"simd与simt混合编程"},{"level":2,"title":"抽象硬件架构","slug":"抽象硬件架构"},{"level":2,"title":"内存层级","slug":"内存层级"},{"level":2,"title":"UB内存分配","slug":"ub内存分配"},{"level":2,"title":"核函数的定义","slug":"核函数的定义"},{"level":2,"title":"调用层级","slug":"调用层级"},{"level":2,"title":"编程示例","slug":"编程示例"}],"relativePath":"guide/编程指南/高级编程/高级AI-Core编程模型/SIMD与SIMT混合编程.md","filePath":"guide/编程指南/高级编程/高级AI-Core编程模型/SIMD与SIMT混合编程.md"}'),u={name:"guide/编程指南/高级编程/高级AI-Core编程模型/SIMD与SIMT混合编程.md"};function g(c,t,d,r,_,q){return a(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="simd与simt混合编程" tabindex="-1">SIMD与SIMT混合编程 <a class="header-anchor" href="#simd与simt混合编程" aria-label="Permalink to &quot;SIMD与SIMT混合编程&quot;">​</a></h1><h2 id="抽象硬件架构" tabindex="-1">抽象硬件架构 <a class="header-anchor" href="#抽象硬件架构" aria-label="Permalink to &quot;抽象硬件架构&quot;">​</a></h2><p>AI Core上SIMD（Single Instruction Multiple Data，单指令多数据）与SIMT（Single Instruction Multiple Thread，单指令多线程）混合编程，结合了SIMD多数据并行计算能力与SIMT离散访存的优势，实现向量级并行与线程级并行的高效协同。当前仅支持Ascend 950PR/Ascend 950DT。</p><p>整个执行过程以Vector Function（VF）为基本调度单位，VF为一个基本函数块。SIMD与SIMT混合编程支持在同一算子中灵活切换SIMD与SIMT执行方式，两种不同类型的VF可以快速切换，每个VF代表一个独立的计算任务片段，通常对应算子中的一段可并行处理的逻辑，从而在性能、能效与开发效率之间取得更优平衡。在SIMD与SIMT混合编程中：</p><ul><li>一个核函数中可包含多个VF。</li><li>每个VF可以选择使用SIMD或SIMT方式进行编程。</li><li>不同类型VF之间可以快速切换，切换粒度为单个VF。</li><li>在同一时刻，一个AIV核只能执行SIMT或SIMD任务。</li></ul><p>在SIMD与SIMT混合编程中，SIMT能够简化复杂算子与不规则控制流的开发；而SIMD基于向量寄存器与指令，实现高效的数据并行处理，即单指令处理多数据，提升每周期的吞吐量。SIMD与SIMT混合编程支持开发者根据算子特征进行精细化映射：规则的逐元素elementwise操作通过SIMD获得高带宽和高算力利用率，不规则或包含分支的计算通过SIMT来缓解发散和控制复杂度。在系统层面，这有利于提高硬件利用率和能效；同时，也更便于进行算子融合和数据复用等优化。同一个算子中既包含SIMD擅长的连续规整计算，也包含SIMT擅长的离散访问等任务，从而在同一算子中同时利用SIMD和SIMT的优势。</p><p>如<a href="./SIMD与SIMT混合编程.html#fig17744131364413">图1</a>所示，SIMD和SIMT的内部执行流程为：</p><ul><li>Scalar计算单元将VF发射到Vector Function Queue中。</li><li>SIMD与SIMT混合编程的工作模式以VF为粒度进行切换，SIMT工作模式下的Data Cache（DCache）数据在VF切换时会被保留。</li><li>SIMD和SIMT之间的VF串序执行，同一时刻，一个AIV核仅能执行SIMD或SIMT任务。</li><li>VF执行完成后，结果数据被写回Unified Buffer或Global Memory。</li></ul><p><strong>图 1</strong> SIMD与SIMT混合编程硬件架构图<br><img src="'+e+'" alt="" title="SIMD与SIMT混合编程硬件架构图"></p><p>SIMD与SIMT编程存在以下差异：</p><p><strong>表 1</strong> SIMD与SIMT核心差异点</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;15.981598159815983%&quot;&gt;&lt;p&gt;维度&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;42.22422242224223%&quot;&gt;&lt;p&gt;SIMD&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;41.7941794179418%&quot;&gt;&lt;p&gt;SIMT&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;15.981598159815983%&quot;&gt;&lt;p&gt;编程模型&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;42.22422242224223%&quot;&gt;&lt;p&gt;单指令多数据（SIMD），基于向量寄存器与向量指令。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;41.7941794179418%&quot;&gt;&lt;p&gt;单指令多线程（SIMT），以线程为单位并行执行。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;15.981598159815983%&quot;&gt;&lt;p&gt;数据搬运方式&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;42.22422242224223%&quot;&gt;&lt;p&gt;通过显式Load/Store将数据从&lt;span&gt;Unified Buffer&lt;/span&gt;搬运到向量寄存器。&lt;/p&gt; &lt;p&gt;不支持直接从&lt;span&gt;Global Memory&lt;/span&gt;搬运数据到SIMD的向量寄存器。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;41.7941794179418%&quot;&gt;&lt;p&gt;支持直接读写&lt;span&gt;Global Memory&lt;/span&gt;或&lt;span&gt;Unified Buffer&lt;/span&gt;中的数据。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;15.981598159815983%&quot;&gt;&lt;p&gt;适用场景&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;42.22422242224223%&quot;&gt;&lt;p&gt;规则、连续的逐元素操作（elementwise），如卷积、矩阵乘法、向量操作等。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;41.7941794179418%&quot;&gt;&lt;p&gt;不规则、含分支、动态访问等复杂逻辑，如注意力机制、稀疏操作等。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>尽管SIMD与SIMT在编程模型和执行机制上有显著差异，但在硬件层面上共享以下关键资源：</p><ul><li>SIMT VF与SIMD VF共享ICache（Instruction Cache），提升指令预取效率。</li><li>SIMT与SIMD共享Vector ALU单元，基于该单元执行的功能和性能基本相同。</li><li>Unified Buffer内存空间中一部分为SIMT与SIMD共享空间，另一部分作为SIMT的Data Cache。</li></ul><h2 id="内存层级" tabindex="-1">内存层级 <a class="header-anchor" href="#内存层级" aria-label="Permalink to &quot;内存层级&quot;">​</a></h2><p>在SIMD与SIMT混合编程场景，可以访问多种内存空间，下表汇总了常见内存类型的作用域及其生命周期。</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.018598140185981%&quot;&gt;&lt;p&gt;内存类型&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.23888376162383762%&quot;&gt;&lt;p&gt;线程作用域&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.928207179282072%&quot;&gt;&lt;p&gt;生命周期&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.514818518148186%&quot;&gt;&lt;p&gt;物理位置&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;51.814818518148186%&quot;&gt;&lt;p&gt;特点&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.018598140185981%&quot;&gt;&lt;p&gt;全局内存&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.23888376162383762%&quot;&gt;&lt;p&gt;所有核的核函数&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.928207179282072%&quot;&gt;&lt;p&gt;应用程序&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.514818518148186%&quot;&gt;&lt;p&gt;Device&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;51.814818518148186%&quot;&gt;&lt;p&gt;大容量，低带宽&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.018598140185981%&quot;&gt;&lt;p&gt;共享内存&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.23888376162383762%&quot;&gt;&lt;p&gt;单核核函数&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.928207179282072%&quot;&gt;&lt;p&gt;核函数&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.514818518148186%&quot;&gt;&lt;p&gt;Vector Core&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;51.814818518148186%&quot;&gt;&lt;p&gt;小容量，高带宽&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.018598140185981%&quot;&gt;&lt;p&gt;SIMT 寄存器&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.23888376162383762%&quot;&gt;&lt;p&gt;Thread&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.928207179282072%&quot;&gt;&lt;p&gt;SIMT VF函数&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.514818518148186%&quot;&gt;&lt;p&gt;Device&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;51.814818518148186%&quot;&gt;&lt;p&gt;极小容量，极高带宽&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;14.018598140185981%&quot;&gt;&lt;p&gt;SIMD 寄存器&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;30.23888376162383762%&quot;&gt;&lt;p&gt;Register File&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.928207179282072%&quot;&gt;&lt;p&gt;SIMD VF函数&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.514818518148186%&quot;&gt;&lt;p&gt;Vector Core&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;51.814818518148186%&quot;&gt;&lt;p&gt;极小容量，极高带宽&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><ul><li>全局内存即Global Memory，存储空间大，带宽低，生命周期与整个应用程序一致，通常用于存储输入输出数据；</li><li>共享内存是每个AIV核拥有的独立Unified Buffer（UB），生命周期和AIV核函数一致，常作为全局内存的缓存；</li><li>最靠近Vector计算单元的是寄存器，SIMT和SIMD模式各自拥有一块私有寄存器内存。</li></ul><p>整体内存架构如下图所示：</p><p><strong>图 2</strong> SIMD与SIMT混合编程内存模型示意图<br><img src="'+o+`" alt="" title="SIMD与SIMT混合编程内存模型示意图"></p><p>在SIMT工作模式下，各个内存的工作流程如下：</p><ul><li>每个线程独立的寄存器和栈，用于存储局部变量。可用寄存器数量与线程块中线程数有关，具体支持情况请见<a href="./../../语言扩展层/SIMT-BuiltIn关键字.html#table1715318510594">表5</a>。</li><li>线程块内所有线程共享本地内存Unified Buffer（UB），该内存区域由线程块内所有线程共同访问，且其生命周期和线程块一致。</li><li>所有线程均可通过Data Cache（DCache）访问全局内存（GM），Data Cache是从UB上单独划分出来的一个缓存空间，内存大小可配置范围为32KB到128KB，具体配置方法详见下文<a href="#section3725125414229">UB内存分配</a>。</li></ul><p>在SIMD工作模式下，各个内存的工作流程如下：</p><ul><li>SIMD的Register File（简称RF）包含多种类型的Reg矢量计算寄存器，用于SIMD VF函数内部存储计算数据，Reg的类型请见<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/RegTensor.md" target="_blank" rel="noreferrer">Reg数据类型定义</a>。</li><li>单核内所有VF Reg寄存器共享内存资源UB。</li><li>在SIMD模式下，不支持直接从全局内存加载数据到Reg矢量计算寄存器，需先将数据从全局内存GM搬运至UB，再通过显式的Load/Store指令，从UB加载到Reg矢量计算寄存器中执行计算操作。</li></ul><h2 id="ub内存分配" tabindex="-1">UB内存分配 <a class="header-anchor" href="#ub内存分配" aria-label="Permalink to &quot;UB内存分配&quot;">​</a></h2><p>UB（即Unified Buffer）内存空间总大小为256KB，参考<a href="#fig184031623113510">图3</a>，按功能划分为四个主要区域，从低地址向高地址依次为静态内存、动态内存、 预留空间 、Data Cache，具体结构如下：</p><ol><li><p>静态内存：从内存的起始地址分配一段指定大小的内存空间，其大小在编译时确定，不可动态修改。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 静态内存通过数组分配，例如：</span></span>
<span class="line"><span>__ubuf__ char staticBuf[1024];</span></span></code></pre></div></li><li><p>动态内存：位于静态内存之后，通过<a href="#li8828116155217">&lt;&lt;&lt;...&gt;&gt;&gt;</a>中参数dynUBufSize指定的动态内存大小空间，可通过以下方式申请使用：</p><ul><li><p>通过TPipe的相关接口申请。</p></li><li><p>通过LocalMemAllocator的Alloc接口申请。</p></li><li><p>使用动态数组分配。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 动态内存通过动态数组分配，例如：</span></span>
<span class="line"><span>extern __ubuf__ char dynamicBuf[];</span></span></code></pre></div></li></ul><p>由于上述三种方法申请动态内存时均从静态内存结束位置之后开始分配，如果同时使用可能会导致地址空间重叠，从而引发未定义行为，因此只能选择其中一种方法进行申请。</p></li><li><p>预留空间：编译器和Ascend C预留空间，大小固定为8KB。</p></li><li><p>Data Cache：SIMT专有的Data Cache空间，内存大小必须大于或等于32KB。</p></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p></p><ul><li>DataCache = UB总大小（256KB） – 静态内存 – 动态内存 – 预留空间(8KB）</li><li>若DataCache小于32KB，会出现校验报错。</li><li>在SIMD与SIMT混合编程的场景下，算子内部不能使用全部的Unified Buffer空间，除了预留8KB空间外，还需至少为SIMT预留32KB的Data Cache空间。</li></ul></div><p><strong>图 3</strong> UB内存分配图<br><img src="`+p+'" alt="" title="UB内存分配图"></p><h2 id="核函数的定义" tabindex="-1">核函数的定义 <a class="header-anchor" href="#核函数的定义" aria-label="Permalink to &quot;核函数的定义&quot;">​</a></h2><ul><li><p>核函数定义方式</p><ul><li><p>SIMT VF函数定义：</p><p>定义SIMT VF核函数时，<a href="./../../语言扩展层/SIMT-BuiltIn关键字.html#li23861114618">__launch_bounds__</a>(thread_num)是可选配置，用于在编译期指定核函数启动的最大线程数，如果不配置thread_num，thread_num默认为1024。</p><p>SIMD与SIMT混合编程中SIMT VF核函数定义的<a href="./../../语言扩展层/SIMD-BuiltIn关键字.html#li611618392141">__simt_vf__</a>、__gm__修饰符需要单独进行标识。关于SIMT VF函数编程的相关约束请参考<a href="./../../../技术附录/CPP标准支持/语法限制/函数.html">函数约束</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__simt_vf__ __launch_bounds__(thread_num) inline void simt_vector_function(__ubuf__ float* input, …)</span></span></code></pre></div></li><li><p>SIMD VF函数定义：</p><p>SIMD VF核函数使用__simd_vf__修饰符进行标识。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__simd_vf__ inline void my_kernel(__gm__ uint8_t* x, __gm__ uint8_t* y, __gm__ uint8_t* z);</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">注意</p><p><strong>SIMD_VF和SIMT_VF的入参只支持PoD（Plain Old Data）数据类型。</strong></p><ul><li>PoD数据类型：包括基础数据类型（int32_t、float等）以及这些基本数据类型组成的数组和结构体；不包括构造函数、析构函数、复制构造函数、复制赋值操作符、非静态成员函数或虚函数的类或结构体。</li></ul></div></li><li><p>SIMD与SIMT混合编程核函数的定义：</p><ol><li>核函数使用__global__、__aicore__修饰符进行标识。</li><li>核函数的入参和SIMD函数的用法一致。</li><li>在SIMD与SIMT混合编程核函数中调用SIMT VF函数和SIMD VF函数。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__global__ __aicore__ void my_kernel(__gm__ float*,…)</span></span></code></pre></div></li></ul></li><li><p>SIMD与SIMT混合核函数调用方式：</p><ol><li><p>核函数的调用请参见<a href="./../../编程模型/AI-Core-SIMD编程/核函数.html">核函数</a>。执行配置由3个参数决定：</p><ul><li>numBlocks：设置核函数启用的核数，通过&lt;&lt;&lt;...&gt;&gt;&gt;的方式传入。</li><li>dynUBufSize：用于指定动态内存大小。动态内存的申请方式请参见UB内存分配中的<a href="#li688923143920">动态内存</a>。</li><li>stream：类型为aclrtStream，用于维护异步操作的执行顺序，确保在device上按照程序中的代码调用顺序执行。</li></ul></li><li><p>开发者需要保证核函数内使用的动态内存大小不超过dynUBufSize，超出会越界访问预留空间或者Data Cache，引发未定义行为。</p></li><li><p>可配置的最大动态内存大小 = 256KB - 保留空间（8KB）- 32KB（最小DCache）- 静态内存。</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kernel_name&lt;&lt;&lt;numBlocks, dynUBufSize, stream&gt;&gt;&gt;(args...)</span></span></code></pre></div></li></ul><h2 id="调用层级" tabindex="-1">调用层级 <a class="header-anchor" href="#调用层级" aria-label="Permalink to &quot;调用层级&quot;">​</a></h2><ul><li>核函数：使用__global__ __aicore__标识，是Device侧的入口函数，在Host侧可以通过&lt;&lt;&lt;...&gt;&gt;&gt;语法进行调用。</li><li>__aicore__函数：使用__aicore__标识该函数在Device侧执行。核函数内可以调用__aicore__函数。</li><li>simd vf函数：使用__simd_vf__标记，能被核函数通过asc_vf_call接口调用。simd vf函数内只能调用__simd_callee__函数和constexpr函数。</li><li>simt vf函数：使用__simt_vf__标记，能被核函数通过asc_vf_call接口调用。simt vf函数内只能调用__simt_callee__函数和constexpr函数。</li><li>__simd_callee__子函数：被simd vf函数调用的子函数，子函数可能有返回值或者通过引用传参，这类子函数通过__simd_callee__标识。__simd_callee__函数内只能调用__simd_callee__函数和constexpr函数。</li><li>__simt_callee__子函数：被simt vf函数调用的子函数，子函数可能有返回值或者通过引用传参，这类子函数通过__simt_callee__标识。__simt_callee__函数内只能调用__simt_callee__函数和constexpr函数。</li></ul><p>具体支持的调用关系图如下所示。</p><p><strong>图 4</strong> 函数调用关系图<br><img src="'+i+`" alt="" title="函数调用关系图"></p><h2 id="编程示例" tabindex="-1">编程示例 <a class="header-anchor" href="#编程示例" aria-label="Permalink to &quot;编程示例&quot;">​</a></h2><p>样例中介绍的算子完整代码请参见<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/00_introduction/03_fusion_operation/gather_adds_simt_simd_hybrid" target="_blank" rel="noreferrer">SIMD与SIMT混合编程实现gather&amp;adds算子样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__simt_vf__ __launch_bounds__(THREAD_COUNT) inline void simt_gather(__gm__ float* input, __gm__ uint32_t* index, __ubuf__ float* gatherOutput, uint32_t inputTotalLength,</span></span>
<span class="line"><span>    uint32_t indexTotalLength, uint32_t outputTotalLength)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    if (threadIdx.x &gt;= outputTotalLength) {</span></span>
<span class="line"><span>        return;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    uint32_t idx = blockIdx.x * blockDim.x + threadIdx.x;</span></span>
<span class="line"><span>    if (idx &gt;= indexTotalLength) {</span></span>
<span class="line"><span>        return;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    uint32_t gatherIdx = index[idx];</span></span>
<span class="line"><span>    if (gatherIdx &gt;= inputTotalLength) {</span></span>
<span class="line"><span>        return;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    gatherOutput[threadIdx.x] = input[gatherIdx];</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>__simd_vf__ inline void simd_adds(__ubuf__ float* output, __ubuf__ float* input, uint32_t count, uint32_t oneRepeatSize, uint16_t repeatTimes)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;float&gt; srcReg0;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;float&gt; dstReg0;</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg maskReg;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    for (uint16_t i = 0; i &lt; repeatTimes; i++) {</span></span>
<span class="line"><span>        maskReg = AscendC::Reg::UpdateMask&lt;float&gt;(count);</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg0, input + i * oneRepeatSize);</span></span>
<span class="line"><span>        AscendC::Reg::Adds(dstReg0, srcReg0, ADDS_ADDEND, maskReg);</span></span>
<span class="line"><span>        AscendC::Reg::StoreAlign(output + i * oneRepeatSize, dstReg0, maskReg);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>__global__ __vector__ void gather_and_adds_kernel(__gm__ float* input, __gm__ uint32_t* index, __gm__ float* output, uint32_t inputTotalLength, uint32_t indexTotalLength)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::LocalMemAllocator&lt;AscendC::Hardware::UB&gt; ubAllocator;</span></span>
<span class="line"><span>    // 1. gather numbers from input.</span></span>
<span class="line"><span>    uint32_t indexTotalLengthPerBlock = indexTotalLength / AscendC::GetBlockNum();</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;float&gt; gatherOutput = ubAllocator.Alloc&lt;float&gt;(indexTotalLengthPerBlock);</span></span>
<span class="line"><span>    asc_vf_call&lt;simt_gather&gt;(</span></span>
<span class="line"><span>        dim3(THREAD_COUNT), input, index, (__ubuf__ float*)gatherOutput.GetPhyAddr(), inputTotalLength,</span></span>
<span class="line"><span>        indexTotalLength, indexTotalLengthPerBlock);</span></span>
<span class="line"><span>    // 2. use reg compute api to do addition.</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;float&gt; addsOutput = ubAllocator.Alloc&lt;float&gt;(indexTotalLengthPerBlock);</span></span>
<span class="line"><span>    constexpr uint32_t oneRepeatSize = AscendC::GetVecLen() / sizeof(float);</span></span>
<span class="line"><span>    uint16_t repeatTimes = (indexTotalLengthPerBlock + oneRepeatSize - 1) / oneRepeatSize;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    asc_vf_call&lt;simd_adds&gt;(</span></span>
<span class="line"><span>        (__ubuf__ float*)addsOutput.GetPhyAddr(), (__ubuf__ float*)gatherOutput.GetPhyAddr(), indexTotalLengthPerBlock,</span></span>
<span class="line"><span>        oneRepeatSize, repeatTimes);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    AscendC::SetFlag&lt;AscendC::HardEvent::V_MTE3&gt;(0);</span></span>
<span class="line"><span>    AscendC::WaitFlag&lt;AscendC::HardEvent::V_MTE3&gt;(0);</span></span>
<span class="line"><span>    // 3. copy data to global memory.</span></span>
<span class="line"><span>    AscendC::GlobalTensor&lt;float&gt; outputGlobalTensor;</span></span>
<span class="line"><span>    outputGlobalTensor.SetGlobalBuffer(output + indexTotalLengthPerBlock * AscendC::GetBlockIdx());</span></span>
<span class="line"><span>    AscendC::DataCopy(outputGlobalTensor, addsOutput, indexTotalLengthPerBlock);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int main(int argc, char *argv[])</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    …</span></span>
<span class="line"><span>    gather_and_adds_kernel&lt;&lt;&lt;numBlocks, dynUBufSize, stream&gt;&gt;&gt;(inputDevice, indexDevice, outputDevice, inputTotalLength, indexTotalLength);</span></span>
<span class="line"><span>    …</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,38)])])}const S=l(u,[["render",g]]);export{I as __pageData,S as default};
